B.Hh=new A.ai(57403,"MaterialIcons",!1)
B.GB=new A.ac("clock","Fallen Cellar Clock","cellar",3,"The old cellar clock lies face-up among the barrels, knocked off its nail in a struggle. The pendulum has snapped and the hands are frozen at 11:05 PM.",B.Hh,B.b2,null,B.t,B.e,null)
