B.jb=new A.ac("cocoa","Cocoa Dusting","cellar",4,"A fine dusting of cocoa powder on the wine rack, with dainty fingermarks in it. One slot in the rack is empty.",B.Ho,B.mW,null,B.t,B.e,null)
B.jd=new A.ac("dismissal","Dismissal Notice","study",4,"Tucked into a gardening manual on the shelf: \u201cB. Tart \u2014 to be let go at month end. The strawberries are a disgrace. \u2014 \xc9.S.\u201d",B.bU,B.a0,null,B.t,B.e,null)
B.Hx=new A.ai(57737,"MaterialIcons",!1)
