B.ns=new A.ac("iou","Crumpled IOU","parlor",1,"Wedged down the side of the armchair: \u201cI, Col. Cannoli, owe Mrs. \xc9. Senclair 50,000 sugar cubes.\u201d",B.HT,B.a0,null,B.t,B.e,null)
B.Hv=new A.ai(57725,"MaterialIcons",!1)
B.nn=new A.ac("sabre","Sticky Sabre","storage",3,"The Colonel's ceremonial sabre, missing from the parlor wall, thrust through the old dress form. The blade is tacky with something dark red.",B.Hv,B.dw,null,B.t,B.e,null)
B.GL=new A.ac("ricottadrip","White Cream Drips","landing",4,"A little pool of thick white ricotta on the landing floorboards, directly below the telephone, and nowhere else.",B.ca,B.i,null,B.t,B.e,null)
B.I5=new A.ai(984301,"MaterialIcons",!1)
B.DT=new A.h(1,0.8823529411764706,0.7450980392156863,0.9058823529411765,B.c)
B.GG=new A.ac("pearls","Empty Pearl Case","study",2,"At the back of the drawer, a velvet jewel case stamped \u201cSenclair Pearls\u201d. It is empty. In the lid, a pawnbroker's ticket dated last month.",B.I5,B.DT,"desk",B.t,B.e,null)
B.N3=s([B.ns,B.nn,B.jd,B.jf,B.je,B.jj,B.np,B.ja,B.jb,B.j8,B.ji,B.jh,B.j7,B.jg,B.GL,B.GG],t.F)
B.PO={urn:0}
B.Wg=new A.d2(B.PO,1,t.fF)
B.GZ=new A.ac("prints","Prints on the Urn","",0,"Three sets of prints came up under the powder. On the lid, Penny Cotta's: she fills it every morning. On the left handle, Tira Misu's. On the right handle, Graham Cracker's.",B.c9,B.cJ,null,B.t,B.e,"churlock")
